function SeasonPassConfMgr:GetExpTotalInLevelZone(fLv, tLv)
    fLv = fLv < 0 and 0 or fLv
    tLv = tLv >= self:GetSeasonPassLevelMaxValue() and self:GetSeasonPassLevelMaxValue() or tLv 
    return self:GetTotalExpAtLevel(tLv) - self:GetTotalExpAtLevel(fLv)
end

---GetRewardsDataByLevelZone
---获取等级区间的奖励 id 合集
---@param fLv integer @ 起始等级
---@param tLv integer @ 最终等级
function SeasonPassConfMgr:GetRewardsDataByLevelZone(fLv, tLv)
    tLv = tLv >= self:GetSeasonPassLevelMaxValue() and self:GetSeasonPassLevelMaxValue() or tLv
    local listRewardIds = {}
    for i = fLv, tLv do      
        local data = self.listReward[i]
        table.insert(listRewardIds,data)            
    end
    return listRewardIds
end

---InitRewardData
---初始化当前排期下的奖励列表
---@param pScheduleId integer @ 排期 Id
function SeasonPassConfMgr:InitRewardData(pScheduleId)
    self.listReward = {}
    local tf = SettingMgr:Get(PATH_ID_GROUP)
    local tableSettings = tf:GetAll()
    for i, v in pairs(tableSettings) do
        local scheduleIdAndLevel = parse_string(v, "scheduleId")
        local scheduleId = checkNumber(string.split(scheduleIdAndLevel, "_")[1])
        local Level = checkNumber(string.split(scheduleIdAndLevel, "_")[2])
        if scheduleId == pScheduleId then
            local rewardIds = parse_string(v, "ids")
            local headIdConReward = string.split(rewardIds, "_")[1]
            local headIdAdvReward = string.split(rewardIds, "_")[2]
            self.listReward[Level] = { headIdConReward, headIdAdvReward }
        end
    end
    self.listReward[self:GetSeasonPassLevelMaxValue() + 1] = { "", "" } -- 巅峰奖励位置
end

