---GetSeasonPassLevelMaxValue
---获取 Pass 卡最大等级
function SeasonPassConfMgr:GetSeasonPassLevelMaxValue()
    if self.seasonPassLevelMax then 
        return self.seasonPassLevelMax 
    end
    local scheduleVo = self:GetScheduleData(BattlePassMgr:GetSeasonPassComp().scheduleId)
    self.seasonPassLevelMax = scheduleVo.maxLv
    return self.seasonPassLevelMax
end

---GetModuleInfo
---获取页面提示
function SeasonPassConfMgr:GetModuleInfo()
    local strResult
    local vo = self:GetParameterData(PARAMETER_TYPE.STRING_MODULE_INFO)
    local strOrigin = self:ConfTxtType(PARAMETER_TYPE.STRING_MODULE_INFO) and vo.txt or vo.num
    strResult = string.gsub(strOrigin, "/n", "\n")
    return vo.name, strResult
end

function SeasonPassConfMgr:ConfTxtType(num)
    return table.isContain(PARAMETER_TYPE_TXT, checkNumber(num))
end

